import{_ as a,c as e,o as t,af as s}from"./chunks/framework.BKeRpnBD.js";const f=JSON.parse('{"title":"22、【賁】 離下艮上","description":"子夏易傳 - 22、【賁】 離下艮上","frontmatter":{"title":"22、【賁】 離下艮上","description":"子夏易傳 - 22、【賁】 離下艮上"},"headers":[],"relativePath":"classics/zixia/024.md","filePath":"classics/zixia/024.md"}'),i={name:"classics/zixia/024.md"};function r(_,p,c,o,n,l){return t(),e("div",null,[...p[0]||(p[0]=[s('<h1 id="_22、【賁】-離下艮上" tabindex="-1">22、【賁】 離下艮上 <a class="header-anchor" href="#_22、【賁】-離下艮上" aria-label="Permalink to “22、【賁】 離下艮上”">​</a></h1><p>卦辭：賁，亨小利有攸往。</p><p>彖曰：賁，亨柔來而文剛，故亨。分剛上而文柔，故小利有攸往。天文也，文明以止，人文也。觀乎天文以察時變，觀乎人文以化成天下。</p><p>子夏：剛下而柔來，文之。天降氣於地而為文也。柔上而分剛，象之地懸，象於天而為文也。天降氣於地，周而通也，故亨。地懸象於上，可以觀文，而則時中，柔而非實，應未足以濟之也，故小利有攸往。皆成文於天也。列尊卑之序，別同異之道，上建治於下，下繫治於上，止而得其治也。觀其天文，可以敬授人時，察其人文，可以自已而化，成天下治也。</p><p>象曰：山下有火，賁。君子以明庶政，無敢折獄。</p><p>子夏：火在山下，其勢至微，君子審其幾，而明以出政，愼以致刑，懼其熾也。及其末也。君子奈之何哉。</p><p>初九，賁，其趾舎車而徒。</p><p>象曰：舎車而徒，義弗乘也。</p><p>子夏：剛而未位，獨立其志，不趨其應，不茍乎乘也。故飾其趾，將徒行也。其義豈乘哉。明其時之不可也。</p><p>六二，賁其須。</p><p>象曰：賁其須，與上興也。</p><p>子夏：得其三而為文，若須之附頤也。柔而位卑，依剛以為文也。</p><p>九三，賁如濡如，永貞吉。</p><p>象曰：永貞之吉，終莫之陵也。</p><p>子夏：剛以得位，兩柔附之，賁然而有文。濡如而沃，其潤雖阻，他應履位，相保可以長守。其正則物不能凌而獲其吉。</p><p>六四，賁如皤如，白馬翰如，匪宼婚媾。</p><p>象曰：六四當位，疑也。匪宼婚媾，終無尤也。</p><p>子夏：得位有應，賁而成文，故潔其儀，白其馬，欲翰如而速往也。懼三為宼，而不敢進，退當位正應，疑何久哉。宼夷則合矣。</p><p>六五，賁於丘園，束帛戔戔，吝終吉。</p><p>象曰：六五之吉，有喜也。</p><p>子夏：不在於彩賁之佳也。柔以居陽，獨保儉德，不因剛以為飾，守中黃以為賁，化之首也。故賁丘園之儉焉，納富用約，故戔戔其束帛，盈也。過儉不飾，雖可惜也。致理於文，終獲其志，故吉有喜也。</p><p>上九，白賁，無咎。</p><p>象曰：白賁無咎，上得志也。</p><p>子夏：剛居柔上，其尚賢也。知存之而不競，保始終而得治者，自得其文也。人之所尚也。其在依柔而後飾哉。超然以素物，無潔矣，又何咎乎。上而逺世，獲乎志也。</p>',24)])])}const m=a(i,[["render",r]]);export{f as __pageData,m as default};
